insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000022', 'en', null, 'Introduction to Political Science', 'A first tour of how politics, power, and government work across the world — ideologies, regimes, institutions, and international relations. Structure adapted from OpenStax Introduction to Political Science (CC BY 4.0), presented neutrally and comparatively rather than from any single country''s viewpoint.', null, 'foundations', 34, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000022', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Political scientist Harold Lasswell summarized politics as deciding…","options":["what is morally right for everyone","who gets what, when, and how","which party should always win","how to abolish government"],"answer":1,"explanation":"Lasswell framed politics as the authoritative distribution of scarce goods — ''who gets what, when, how'' — see ''Politics, power, and authority''."},{"prompt":"Authority differs from raw power mainly because authority is…","options":["always backed by the military","power that people accept as legitimate","only found in democracies","the same thing as wealth"],"answer":1,"explanation":"Authority is power widely regarded as legitimate, so people comply willingly — see ''Politics, power, and authority''."},{"prompt":"Classical liberalism places the greatest emphasis on…","options":["state ownership of industry","individual liberty and limited government","rule by a hereditary monarch","abolishing all private property"],"answer":1,"explanation":"Classical liberalism centers individual rights, liberty, and limited government — see ''Political ideologies''."},{"prompt":"A regime where power is concentrated in rulers who face little accountability and limit competition is best called…","options":["a democracy","an authoritarian regime","a federation","a bicameral system"],"answer":1,"explanation":"Authoritarian regimes restrict competition and accountability — see ''Forms of government''."},{"prompt":"In a parliamentary system, the head of government (e.g. a prime minister) usually comes from…","options":["a separate nationwide election","the legislature''s majority","the judiciary","the military high command"],"answer":1,"explanation":"Parliamentary executives are drawn from and accountable to the legislature — see ''Institutions''."},{"prompt":"Judicial review is the power of courts to…","options":["write new legislation","judge whether laws conform to the constitution","elect the head of state","collect taxes"],"answer":1,"explanation":"Judicial review lets courts assess laws against the constitution — see ''Institutions''."},{"prompt":"In international relations, ''sovereignty'' refers to a state''s…","options":["duty to obey the United Nations","supreme authority over its own territory","membership in a military alliance","size of its economy"],"answer":1,"explanation":"Sovereignty is a state''s supreme authority within its borders — see ''Comparative politics and international relations''."},{"prompt":"''Civil society'' generally means…","options":["the armed forces","voluntary associations and groups independent of the state","the elected legislature","the national court system"],"answer":1,"explanation":"Civil society is the web of voluntary, non-state associations — see ''Key terms''."},{"prompt":"Comparative politics is best described as the study that…","options":["compares political systems to explain their differences","only studies one country''s laws","predicts stock prices","ranks countries from best to worst"],"answer":0,"explanation":"Comparative politics compares systems to explain variation, not to rank them — see ''Comparative politics and international relations''."}]}'::jsonb, null, 10),
  (2, 'Politics, power, and authority', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define politics, and tell the difference between power, authority, and legitimacy. Warm-up: from the diagnostic, whose one-line definition of politics was ''who gets what, when, and how''?"},{"heading":"The idea","text":"*Politics* is how a group makes binding collective decisions about shared rules and scarce resources when its members disagree. *Power* is the ability to get others to act as you wish, even against their preferences. *Authority* is power that people accept as *legitimate*, so they comply without being forced. The sociologist Max Weber described three sources of legitimate authority: *traditional* (custom and inheritance), *charismatic* (the personal appeal of a leader), and *legal-rational* (rules, offices, and constitutions). These ideas travel across every political system, from village councils to global bodies."},{"heading":"Worked example","text":"Consider three leaders. A queen who rules because her family always has relies on *traditional* authority. A movement founder whose followers obey out of devotion relies on *charismatic* authority. A tax official you obey because the law defines the office relies on *legal-rational* authority. Notice that a ruler who governs only through fear has power but thin legitimacy — which tends to make rule costly and unstable."},{"heading":"Your turn","text":"Classify the source of authority: (1) a chief whose title passes down the family line, (2) an elected minister acting under a written constitution, (3) a protest leader followed for personal inspiration, (4) a monarch crowned by centuries-old custom. Answers: 1-traditional, 2-legal-rational, 3-charismatic, 4-traditional."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating power as only force — persuasion, money, and agenda-setting are power too. Mistake: assuming any government that holds power is seen as legitimate. Exit: (a) Which of Weber''s types rests on rules and offices? (b) In one word, what does authority add to raw power? Answers: legal-rational; legitimacy."}]}'::jsonb, 'Keep two words apart all course: power = the ability to influence; authority = power seen as legitimate.', 12),
  (3, 'Political ideologies', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a political ideology is and summarize several major ones neutrally. Warm-up: which tradition puts individual liberty and limited government at its center?"},{"heading":"The idea","text":"A *political ideology* is a coherent set of beliefs about how society should be organized and what government is for. Each answers a shared question: how much should the state do, and toward what ends? *Liberalism* stresses individual liberty, rights, and limited government (in its classical form it also favors free markets). *Conservatism* values tradition, stability, established institutions, and gradual change. *Socialism* stresses social and economic equality, favoring public provision or regulation to reduce inequality. Other families include *anarchism* (deep skepticism of state authority), *nationalism* (loyalty to a national community), and *green/environmentalism* (ecological sustainability as a priority). None is ''the correct one'' — they are rival value packages debated worldwide."},{"heading":"Worked example","text":"Two questions help map ideologies: how large a role should the state play in the economy, and how quickly should society change? A view favoring markets and gradual change sits near classical liberalism/conservatism; one favoring public ownership and rapid equalization sits near socialism. A caution: the word ''liberal'' means market-oriented liberty in much of Europe and Latin America but often signals a center-left position in the United States — so labels depend on where you stand."},{"heading":"Your turn","text":"Match the emphasis to an ideology: (1) preserve traditional institutions and change slowly, (2) maximize individual liberty and limited government, (3) reduce inequality through collective ownership or strong regulation, (4) minimize or abolish state authority. Answers: 1-conservatism, 2-liberalism, 3-socialism, 4-anarchism."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming ''liberal'' means the same thing everywhere. Mistake: treating ''left'' and ''right'' as fixed, universal categories rather than relative labels. Exit: (a) In one phrase, what question do all ideologies answer? (b) Name one ideology skeptical of state authority. Answers: how much the state should do and to what end; anarchism (nationalism or others may also apply)."}]}'::jsonb, 'Ideologies describe competing values, not facts to score as right or wrong — describe each on its own terms.', 13),
  (4, 'Forms of government', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Classify governments by regime type and by how power is organized. Warm-up: what feature most clearly marks a regime as a democracy?"},{"heading":"The idea","text":"One way to classify governments asks who rules and how accountable they are. A *democracy* selects rulers through free, fair, and competitive elections, protects civil liberties, and upholds the rule of law. An *authoritarian* regime concentrates power, restricts competition, and offers limited accountability. A *totalitarian* regime is the extreme case, seeking to control nearly all of public and private life. Many real states are *hybrid regimes* sitting between these poles. A second, structural question asks how power is arranged: *presidential* systems have a separately elected executive, while *parliamentary* systems fuse the executive into the legislature; *unitary* states concentrate authority centrally, while *federal* states divide it between national and regional governments."},{"heading":"Worked example","text":"Compare structures with global cases, factually and without ranking them. Germany and India are *federal* systems that spread power across regions; France and Japan are more *unitary*. The United States uses a *presidential* system with a separately elected executive, while the United Kingdom and Canada use *parliamentary* systems where the prime minister leads the legislative majority. Regime type and structure are independent: a country can be democratic and federal, or democratic and unitary."},{"heading":"Your turn","text":"Classify each: (1) rulers chosen by free, competitive elections with protected rights, (2) a single party bans opposition and controls the press, (3) authority split between national and regional governments, (4) an executive drawn from and removable by the legislature, (5) a state seeking total control over economic, social, and private life. Answers: 1-democracy, 2-authoritarian, 3-federal, 4-parliamentary, 5-totalitarian."},{"heading":"Common mistakes & exit ticket","text":"Mistake: equating democracy with elections alone — genuine democracy also needs rule of law, civil liberties, and real competition. Mistake: assuming every democracy is presidential (most are parliamentary). Exit: (a) Beyond elections, name one thing a democracy requires. (b) In which system is the executive fused with the legislature? Answers: rule of law / civil liberties / fair competition; parliamentary."}]}'::jsonb, 'Two separate questions: who rules and how accountable they are (regime), versus how power is structured (presidential/parliamentary, unitary/federal).', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Politics, at its core, is about…","options":["making collective decisions when people disagree","eliminating all disagreement","maximizing one person''s wealth","avoiding all rules"],"answer":0,"explanation":"Politics manages disagreement over shared rules and resources."},{"prompt":"Legal-rational authority rests on…","options":["personal charisma","inherited custom","rules, offices, and constitutions","military force alone"],"answer":2,"explanation":"Legal-rational authority flows from impersonal rules and offices."},{"prompt":"Which best matches conservatism''s core emphasis?","options":["rapid social transformation","tradition, stability, and gradual change","abolishing the state","public ownership of all industry"],"answer":1,"explanation":"Conservatism values continuity and gradual change."},{"prompt":"A hybrid regime is one that…","options":["has no government at all","sits between full democracy and full authoritarianism","is always totalitarian","has only a judiciary"],"answer":1,"explanation":"Hybrid regimes mix democratic and authoritarian features."},{"prompt":"In a presidential system, the executive is…","options":["chosen by the courts","elected separately from the legislature","always a monarch","the same person as the chief justice"],"answer":1,"explanation":"Presidential executives are separately elected."},{"prompt":"The claim ''liberal means the same thing everywhere'' is…","options":["true worldwide","false — its meaning shifts by country","only about economics","a law of politics"],"answer":1,"explanation":"''Liberal'' signals market-liberty in some countries and center-left in others."}]}'::jsonb, null, 8),
  (6, 'Institutions: executives, legislatures, and courts', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the three main branches of government and describe what each does. Warm-up: which branch has the job of interpreting the law?"},{"heading":"The idea","text":"*Institutions* are the enduring rules and organizations through which societies govern themselves. The *legislature* makes laws and represents citizens; it may be *unicameral* (one chamber) or *bicameral* (two). The *executive* implements and enforces laws; some systems split the *head of state* (a symbolic role) from the *head of government* (who runs day-to-day affairs). The *judiciary* interprets law and resolves disputes, and in many systems exercises *judicial review* over whether laws fit the constitution. Systems differ in how they relate these branches: *separation of powers* with checks and balances keeps them distinct and mutually limiting, while parliamentary *fusion* links the executive to the legislative majority. An independent judiciary is widely seen as essential to the rule of law."},{"heading":"Worked example","text":"Trace a law''s life. A bill is proposed and debated in the *legislature*; if passed, the *executive* signs and enforces it; if someone challenges it, a court may test it against the constitution through *judicial review*. Constitutional courts in states such as Germany and South Africa perform this review, illustrating that the practice is global, not tied to any one country."},{"heading":"Your turn","text":"Match the branch to its function: (1) writes and passes laws, (2) enforces and administers laws, (3) interprets laws and settles disputes, (4) has two legislative chambers, (5) tests a law against the constitution. Answers: 1-legislature, 2-executive, 3-judiciary, 4-bicameral (legislature), 5-judiciary (judicial review)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming the executive is always a president — many executives are prime ministers or split head-of-state/head-of-government roles. Mistake: thinking courts freely invent policy; they interpret law within legal limits. Exit: (a) Which branch exercises judicial review? (b) Name the two-chamber legislature term. Answers: the judiciary; bicameral."}]}'::jsonb, 'Three core functions to keep straight: legislatures make law, executives carry it out, courts interpret it.', 12),
  (7, 'Comparative politics and international relations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish comparative politics from international relations and name key concepts in each. Warm-up: what do we call a state''s supreme authority over its own territory?"},{"heading":"The idea","text":"*Comparative politics* compares political systems to explain why they differ — why some states democratize, why institutions vary, why policies diverge. *International relations* (IR) studies how states and other actors interact across borders. Central IR concepts include *sovereignty* (a state''s supreme authority at home), *anarchy* (no government above states), and the state system often traced to the 1648 Peace of Westphalia. IR offers several analytical lenses, described here neutrally: *realism* stresses power, security, and self-interest under anarchy; *liberalism/institutionalism* stresses cooperation through trade, law, and organizations; *constructivism* stresses how ideas, norms, and identities shape behavior. Actors include states, intergovernmental organizations like the UN, NGOs, and multinational corporations."},{"heading":"Worked example","text":"Take one event — two states signing a trade and security pact — and view it through each lens. A *realist* reads it as balancing against a rival''s power. A *liberal/institutionalist* reads it as cooperation that lowers the cost of conflict and boosts mutual gains. A *constructivist* reads it as two states acting on a shared identity or norm. Same event, three explanations: the lenses are tools, not verdicts."},{"heading":"Your turn","text":"Match concept to description: (1) no authority sits above states, (2) a state''s supreme authority within its borders, (3) lens emphasizing power and security, (4) lens emphasizing institutions and cooperation, (5) lens emphasizing ideas and identity. Answers: 1-anarchy, 2-sovereignty, 3-realism, 4-liberalism/institutionalism, 5-constructivism."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking IR is only about war — trade, law, human rights, and cooperation are just as central. Mistake: treating sovereignty as absolute; treaties and interdependence constrain it in practice. Exit: (a) Which field compares systems to explain their differences? (b) Which IR lens emphasizes cooperation through institutions? Answers: comparative politics; liberalism/institutionalism."}]}'::jsonb, 'Comparative politics looks inside and across states; international relations looks at how states and other actors interact.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"power","translation":"the ability to get others to act as you want, even against their preferences","example":"A government uses law, money, and persuasion as forms of power."},{"term":"authority","translation":"power that people accept as legitimate, so they comply without force","example":"An elected official governs through authority, not fear."},{"term":"ideology","translation":"a coherent set of beliefs about how society should be organized and what government is for","example":"Liberalism, conservatism, and socialism are political ideologies."},{"term":"democracy","translation":"a system where rulers are chosen by free, fair, competitive elections under the rule of law","example":"A democracy needs civil liberties, not just elections."},{"term":"sovereignty","translation":"a state''s supreme authority over its own territory","example":"Sovereignty means no outside body can rule a state''s internal affairs by right."},{"term":"civil society","translation":"the voluntary associations and groups that are independent of the state","example":"Charities, unions, and community groups make up civil society."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The branch of government that makes laws is the…","options":["judiciary","legislature","executive","civil service"],"answer":1,"explanation":"Legislatures make and pass laws."},{"prompt":"Judicial review allows courts to…","options":["elect the president","test laws against the constitution","declare war","set tax rates"],"answer":1,"explanation":"Courts assess whether laws conform to the constitution."},{"prompt":"A bicameral legislature has…","options":["no elected members","two chambers","only a president","three courts"],"answer":1,"explanation":"''Bi-'' means two chambers."},{"prompt":"In international relations, ''anarchy'' means…","options":["total chaos and violence","no authority sits above sovereign states","the absence of any states","rule by one empire"],"answer":1,"explanation":"Anarchy here means no world government above states, not disorder."},{"prompt":"The realist lens in IR emphasizes…","options":["power and security under anarchy","shared identities and norms","the abolition of all states","domestic court rulings"],"answer":0,"explanation":"Realism centers power, security, and self-interest."},{"prompt":"Civil society is made up of…","options":["government ministries","voluntary, non-state associations","the armed forces","the constitutional court"],"answer":1,"explanation":"Civil society is voluntary and independent of the state."}]}'::jsonb, null, 8),
  (10, 'Applied project: compare two countries'' political systems', 'writing', '{"sections":[{"heading":"The task","text":"Choose two countries from different regions of the world and write a short, balanced comparison of their political systems. Stay descriptive and non-partisan: your goal is to explain how each system works and why they differ, not to judge which country is ''better''."},{"heading":"Milestones","text":"1) Classify each country''s regime type (democracy, authoritarian, hybrid) and justify it with evidence about elections, rights, and rule of law. 2) Identify each country''s structure: presidential or parliamentary, unitary or federal. 3) Describe how each arranges its legislature, executive, and judiciary. 4) Note one role civil society or political participation plays in each. 5) Offer one comparative-politics explanation for a key difference between them."},{"heading":"Self-check rubric","text":"✔ Both countries come from different world regions (not US-only). ✔ Each regime classification is backed by concrete evidence, not opinion. ✔ You correctly used structural terms (presidential/parliamentary, unitary/federal). ✔ You described all three branches for each country. ✔ Your tone stayed neutral across ideologies and systems. If all five hold, you''ve reasoned like a comparative political scientist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000022' and l.position = v.pos
);
